parameters.jsCode:
const context = $("Load Draft Context").first().json;
const deepseek = $input.first().json;

let draft;

try {
  const content = deepseek.choices?.[0]?.message?.content;

  if (typeof content === "string") {
    draft = JSON.parse(content);
  } else if (typeof content === "object" && content !== null) {
    draft = content;
  } else {
    draft = {
      valid: false,
      block_reason: "deepseek_response_missing_content"
    };
  }
} catch (error) {
  draft = {
    valid: false,
    block_reason: "deepseek_response_not_valid_json"
  };
}

const evidence = context.evidence || [];
const step = context.step || {};
const score = context.score || {};
const lead = context.lead || {};
const queue = context.queue || {};

const errors = [];

if (!Array.isArray(evidence) || evidence.length === 0) {
  errors.push("missing_score_evidence");
}

if (!draft.subject || String(draft.subject).trim().length === 0) {
  errors.push("missing_subject");
}

if (!draft.body || String(draft.body).trim().length === 0) {
  errors.push("missing_body");
}

if (draft.subject && String(draft.subject).length > 70) {
  errors.push("subject_too_long");
}

if (draft.body && String(draft.body).split(/\s+/).filter(Boolean).length > 160) {
  errors.push("body_too_long");
}

if (!draft.observation_used || String(draft.observation_used).trim().length < 10) {
  errors.push("missing_observation");
}

if (!draft.automation_idea || String(draft.automation_idea).trim().length < 10) {
  errors.push("missing_automation_idea");
}

if (!draft.cta || String(draft.cta).trim().length < 5) {
  errors.push("missing_cta");
}

const forbidden = [
  "guaranteed",
  "i noticed your business is struggling",
  "you are losing customers",
  "we can 10x",
  "limited time offer",
  "act now",
  "free money",
  "risk-free"
];

const combined = `${draft.subject || ""} ${draft.body || ""}`.toLowerCase();

for (const phrase of forbidden) {
  if (combined.includes(phrase)) {
    errors.push(`forbidden_phrase:${phrase}`);
  }
}

const hasLink = /https?:\/\//i.test(draft.body || "");

const stepAllowsLink =
  step.allow_link === true ||
  step.requires_link === true ||
  step.include_link === true;

if (hasLink && !stepAllowsLink) {
  errors.push("link_not_allowed_for_step");
}

const isValid = draft.valid === true && errors.length === 0;

return [
  {
    json: {
      queue_id: queue.id,
      lead_id: lead.id || queue.lead_id,
      band: score.band,
      step_number: queue.current_step,
      draft,
      validation_errors: errors,
      is_valid: isValid,
      approval_status:
        isValid && score.band === "A" && queue.current_step === 1
          ? "pending"
          : isValid
            ? "auto_approved"
            : "blocked"
    }
  }
];

parameters.body:
={{
  JSON.stringify({
    p_queue_id: $json.queue_id,
    p_lead_id: $json.lead_id,
    p_is_valid: Boolean($json.is_valid),
    p_subject: $json.draft?.subject || null,
    p_body: $json.draft?.body || null,
    p_channel: $json.draft?.channel || "email",
    p_approval_status: $json.approval_status || ($json.is_valid ? "auto_approved" : "blocked"),
    p_block_reason: Array.isArray($json.validation_errors) && $json.validation_errors.length > 0
      ? $json.validation_errors.join(", ")
      : ($json.draft?.block_reason || null),
    p_raw_draft: $json.draft || {}
  })
}}
